    ('1'::bigint,'1'::bigint,'1'::integer,'ESQUEMA 12 - Beta actual'::character varying(150),'2026-09-01'::date,NULL::date,'BORRADOR'::character varying(20),'Beta ESQUEMA 12 confirmada el 21/09/2026: jornadas de lunes a sabado con tolerancia de 5 minutos y 60 minutos de refrigerio; personal virtual sin marcacion ni bono de cumplimiento; metas SafetyPay vigentes; error de cuadro 30/60/90 sobre comisiones del mes; error critico por 100% del monto perdido, fraccionable en varios meses.'::text,NULL::timestamp with time zone,NULL::bigint,NULL::bigint,'2026-09-22 01:55:37.681376+00'::timestamp with time zone,'2026-09-22 03:26:25.513654+00'::timestamp with time zone)
